// Fábrica de iconos SVG reales (no emojis). ICO(path, {s,c,stroke,sw,mr}).
const ICO = (inner: string, o: { s?: number; c?: string; stroke?: boolean; sw?: number; mr?: number; va?: number } = {}) => {
  const s = o.s || 20, c = o.c || '#fff'
  const mr = o.mr != null ? `margin-right:${o.mr}px;` : ''
  const va = o.va != null ? o.va : -2
  const fs = o.stroke ? `fill="none" stroke="${c}" stroke-width="${o.sw || 2}" stroke-linecap="round" stroke-linejoin="round"` : `fill="${c}"`
  return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" ${fs} style="vertical-align:${va}px;flex-shrink:0;${mr}">${inner}</svg>`
}
