// 5 estrellas doradas (prueba social).
const STARS = [0, 0, 0, 0, 0].map(() => ICO(P.star, { s: 15, c: '#fbbf24', va: -2 })).join('')
// Iconos que se dibujan con CONTORNO (line icons). El resto van rellenos.
const STROKE_ICONS = new Set([P.check, P.shield, P.target, P.clock, P.calendar, P.chart, P.users, P.pin, P.scissors, P.link, P.rocket, P.phone, P.instagram])
// Badge cuadrado con icono (tinte del color de acento). Auto-detecta contorno vs relleno.
const iconBadge = (path: string, accent: string, glow: string, size = 46) =>
  `<div style="width:${size}px;height:${size}px;border-radius:13px;background:rgba(${glow},.15);border:1px solid rgba(${glow},.4);display:inline-flex;align-items:center;justify-content:center;">${ICO(path, { s: Math.round(size * 0.46), c: accent, stroke: STROKE_ICONS.has(path), sw: 2 })}</div>`
// Estilo de input de formulario reutilizable.
const INP = 'width:100%;box-sizing:border-box;background:#0b0f1a;border:1px solid rgba(255,255,255,.14);border-radius:12px;padding:14px;color:#fff;font-size:14px;margin-bottom:12px;outline:none;'
// Recolorea un HTML cambiando los tokens de color (para variantes de una misma plantilla).
const recolorHtml = (html: string, pairs: [string, string][]) =>
  pairs.reduce((s, [a, b]) => s.split(a).join(b), html)

